public sealed partial class CutsceneEditor {
    static double[] FlickerMetrics(IList<Frame> frames){long changed=0,pairs=0;double sum=0;for(int n=1;n<frames.Count;n++)for(int p=0;p<frames[n].Data.Length;p+=4){var a=frames[n].Data;var b=frames[n-1].Data;if(a[p+3]<128||b[p+3]<128)continue;int d=Math.Max(Math.Abs(a[p]-b[p]),Math.Max(Math.Abs(a[p+1]-b[p+1]),Math.Abs(a[p+2]-b[p+2])));pairs++;sum+=d;if(d>0)changed++;}return new[]{pairs==0?0:100.0*changed/pairs,pairs==0?0:sum/pairs};}
    static ulong SequenceHash(IList<Frame> frames){ulong hash=1469598103934665603;unchecked{foreach(var f in frames)foreach(byte b in f.Data)hash=(hash^b)*1099511628211;}return hash;}
    static double RegionChanges(IList<Frame> frames,int left,int top,int right,int bottom){long changes=0,pairs=0;for(int n=1;n<frames.Count;n++)for(int y=top;y<bottom;y++)for(int x=left;x<right;x++){int p=(y*frames[n].W+x)*4;var a=frames[n].Data;var b=frames[n-1].Data;if(a[p+3]<128||b[p+3]<128)continue;pairs++;if(a[p]!=b[p]||a[p+1]!=b[p+1]||a[p+2]!=b[p+2])changes++;}return pairs==0?0:100.0*changes/pairs;}
